function tooltipCss(opts){
  opts=opts||{};
  var bg=opts.bg||'#1f2937';
  var color=opts.color||'#ffffff';
  var radius=opts.radius!=null?opts.radius:6;
  var pos=opts.position||'top';
  var dist=opts.distance!=null?opts.distance:8;
  var L=[];
  L.push('.tooltip { position: relative; }');
  L.push('.tooltip::after {');
  L.push('  content: attr(data-tip);');
  L.push('  position: absolute;');
  if(pos==='top') L.push('  bottom: calc(100% + '+dist+'px); left: 50%; transform: translateX(-50%);');
  else if(pos==='bottom') L.push('  top: calc(100% + '+dist+'px); left: 50%; transform: translateX(-50%);');
  else if(pos==='left') L.push('  right: calc(100% + '+dist+'px); top: 50%; transform: translateY(-50%);');
  else L.push('  left: calc(100% + '+dist+'px); top: 50%; transform: translateY(-50%);');
  L.push('  background: '+bg+';');
  L.push('  color: '+color+';');
  L.push('  padding: 6px 10px;');
  L.push('  border-radius: '+radius+'px;');
  L.push('  font-size: 13px;');
  L.push('  white-space: nowrap;');
  L.push('  opacity: 0; pointer-events: none;');
  L.push('  transition: opacity .15s ease;');
  L.push('}');
  L.push('.tooltip:hover::after { opacity: 1; }');
  return L.join('\n');
}

var EXPORTS={tooltipCss:tooltipCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TooltipForgePure = EXPORTS; }
